<template>
 <aside class="cv-convs qg-glass qcw-shelf" :class="{open}" :aria-label="t('history.list')">
  <header class="qcw-heading"><span class="qcw-book" aria-hidden="true"><ClientIcon name="folder"/><i>Q</i></span><span><small>QGauss / CHAPTERS</small><b>{{ ct(trash?'对话回收站':'你的灵感档案') }}</b></span><div class="qcw-head-actions"><button type="button" class="qcw-icon" :disabled="loading||busy" :aria-label="ct('刷新会话档案')" @click="emit('refresh')"><BrandLoader v-if="loading" :size="14"/><ClientIcon v-else name="refresh"/></button><button type="button" class="qcw-icon" :aria-label="ct(trash?'回到会话档案':'打开对话回收站')" :aria-pressed="trash" @click="emit('trash',!trash)"><ClientIcon :name="trash?'chat':'trash'"/></button></div></header>
  <div class="qcw-create-row"><button type="button" class="cv-new" :title="t('history.newShortcut')" @click="emit('start')"><ClientIcon name="plus"/><span>{{ t('history.start') }}</span></button><button type="button" class="qcw-icon" :aria-label="t('history.search')" :aria-expanded="searchOpen" @click="searchOpen=!searchOpen"><ClientIcon name="search"/></button></div>
  <label v-if="searchOpen||query" class="cv-search"><ClientIcon name="search"/><input :value="query" :aria-label="t('history.searchLabel')" :placeholder="ct('找回一个标题或关键词')" maxlength="120" @input="emit('query',$event.target.value)"/><button v-if="query" type="button" :aria-label="ct('清除会话搜索')" @click="emit('query','')"><ClientIcon name="close"/></button></label>
  <div class="qgc-history-tabs" role="tablist" :aria-label="t('history.kinds')"><button v-for="tab in kinds" :key="tab.key" type="button" role="tab" :aria-label="t(tab.label)" :aria-selected="kind===tab.key" @click="emit('kind',tab.key)"><span class="qcw-tab-name">{{ t(tab.label) }}</span><small v-if="Number.isFinite(kindCounts[tab.key])">{{ kindCounts[tab.key] }}</small></button></div>
  <div v-if="folders.length" class="cv-folders" role="tablist" :aria-label="t('history.folders')"><button type="button" class="cv-folder" :class="{active:!folder}" :aria-label="t('history.all')" :aria-selected="!folder" role="tab" @click="emit('folder','')">{{ t('history.all') }}</button><button type="button" class="cv-folder" :class="{active:folder==='unfiled'}" :aria-label="ct('未分组')" :aria-selected="folder==='unfiled'" role="tab" @click="emit('folder','unfiled')">{{ ct('未分组') }}</button><button v-for="item in folders" :key="item.id" type="button" role="tab" class="cv-folder" :class="{active:folder===item.id}" :aria-selected="folder===item.id" :aria-label="item.name" :title="item.name" @click="emit('folder',item.id)" @dblclick="emit('folderCommand',item,'rename')"><span>{{ item.name }}</span><small>{{ Number.isFinite(total)?(folderCounts[item.id]||0):'—' }}</small></button></div>
  <div v-if="activeFolder" class="cv-folder-bar"><span :title="activeFolder.name">{{ activeFolder.name }}</span><button type="button" :disabled="busy" @click="emit('folderCommand',activeFolder,'rename')">{{ t('history.rename') }}</button><button type="button" :disabled="busy" @click="emit('folderCommand',activeFolder,'remove')">{{ t('history.deleteFolder') }}</button></div>
  <p class="qcw-status">{{ ct(trash?'好故事，随时可以回来。':'每一段灵感，都有自己的位置。') }}</p>
  <div v-if="error" class="qcw-error" role="alert"><b>{{ ct('最新记录暂未确认') }}</b><span>{{ ct(error) }}</span><button type="button" :disabled="loading" @click="emit('refresh')">{{ ct('重新打开档案') }}</button></div>
  <div class="cv-convs-list" :aria-busy="loading||loadingMore">
   <div v-if="loading&&!groups.length" class="qcw-loading" role="status"><BrandLoader :size="36" :text="ct('正在打开你的故事…')"/></div>
   <template v-for="group in groups" :key="group.key"><div class="cv-group">{{ group.label }}<small>{{ group.items.length }}</small></div><div v-for="row in group.items" :key="row.id" class="cv-conv" :class="{active:!selecting&&row.id===activeId,picked:selecting&&selected.includes(row.id)}" :role="selecting?'checkbox':'button'" :aria-checked="selecting?selected.includes(row.id):undefined" :aria-label="row.title||t('chat.new')" tabindex="0" @click="emit('choose',row)" @keydown.enter.prevent="emit('choose',row)" @keydown.space.prevent="emit('choose',row)">
    <span v-if="selecting" class="cv-check" aria-hidden="true"><ClientIcon v-if="selected.includes(row.id)" name="check"/></span><span class="qcw-row-copy"><span class="cv-conv-title" :title="row.title">{{ row.title||t('chat.new') }}</span><small><span v-if="row.statusUnknown" role="status">{{ ct('对话状态待核对') }}</span><span v-else-if="row.activeMessageId" class="qgd-run-badge" role="status">{{ t(row.activeMessageStatus==='SETTLING'?'history.settling':'history.generating') }}</span><span v-else>{{ ct('共 {count} 条消息',{count:Number.isFinite(row.messageCount)?row.messageCount:'—'}) }}</span><i v-if="row.pinned&&!trash" :title="t('history.pinned')">✦</i></small></span>
    <button v-if="trash" type="button" class="qcw-restore" :disabled="busy" :aria-label="ct('恢复对话：{name}',{name:row.title||t('chat.new')})" @click.stop="emit('restore',row)"><ClientIcon name="refresh"/><span>{{ ct('恢复') }}</span></button>
    <span v-else-if="!selecting" class="cv-conv-ops" @click.stop><el-dropdown trigger="click" size="small" @command="command=>emit('command',row,command)"><button type="button" class="cv-op" :disabled="busy" :title="t('history.more')" :aria-label="t('history.actions')">•••</button><template #dropdown><el-dropdown-menu><el-dropdown-item command="pin">{{ t(row.pinned?'history.unpin':'history.pin') }}</el-dropdown-item><el-dropdown-item command="rename">{{ t('history.rename') }}</el-dropdown-item><el-dropdown-item v-for="item in folders" :key="item.id" :command="'move:'+item.id" :disabled="row.folderId===item.id">{{ t('history.moveTo',{name:item.name}) }}</el-dropdown-item><el-dropdown-item v-if="row.folderId" command="unfolder">{{ t('history.unfolder') }}</el-dropdown-item><el-dropdown-item command="newfolder">{{ t('history.newFolder') }}</el-dropdown-item><el-dropdown-item command="delete" divided>{{ ct('移到对话回收站') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></span>
   </div></template>
   <div v-if="!loading&&!groups.length&&!error" class="qgc-history-empty"><span class="qcw-empty-book" aria-hidden="true"><ClientIcon :name="trash?'trash':'chat'"/></span><b>{{ ct(trash?'这里，暂时没有旧故事。':authenticated?'还没有找到这段灵感。':'登录后，把故事留在这里。') }}</b><small>{{ ct(trash?'恢复的对话会带回原消息与记录。':query||folder?'换个关键词，或看看其他分组。':'开始一次对话，它会出现在这里。') }}</small></div>
   <button v-if="hasMore" type="button" class="qcw-more" :disabled="loadingMore||loading" @click="emit('more')"><BrandLoader v-if="loadingMore" :size="16"/><ClientIcon v-else name="plus"/>{{ ct(loadingMore?'正在找回更多故事…':'继续打开更早的对话') }}</button>
  </div>
  <p v-if="authenticated&&Number.isFinite(total)" class="qcw-count">{{ ct('已打开 {loaded} 段，共 {total} 段',{loaded:loaded,total}) }}</p>
  <div v-if="selecting&&!trash" class="cv-bulk"><div class="cv-bulk-info"><span>{{ t('history.selected',{count:selected.length}) }}</span><button type="button" class="cv-link" @click="emit('selectAll')">{{ t(allSelected?'history.deselectAll':'history.selectAll') }}</button></div><button type="button" class="qcw-bulk-remove" :disabled="!selected.length||busy||loading||!!error" @click="emit('removeSelected')">{{ ct('把选中的对话移入回收站') }}</button></div>
  <div class="qgc-history-operations"><button type="button" :disabled="trash||busy" :aria-label="t(selecting?'history.exitManage':'history.manage')" :title="t(selecting?'history.exitManage':'history.manage')" @click="emit('manage')"><ClientIcon name="check"/><span>{{ t(selecting?'history.exitManage':'history.manage') }}</span></button><button type="button" :disabled="trash||!unpinnedTotal||busy||loading||!!error" :aria-label="t('history.clearUnpinnedShort')" :title="t('history.clearUnpinnedShort')" @click="emit('clearUnpinned')"><ClientIcon name="trash"/><span>{{ t('history.clearUnpinnedShort') }}</span></button><button type="button" :disabled="busy" :aria-label="t('history.folders')" :title="t('history.folders')" @click="emit('addFolder')"><ClientIcon name="folder"/><span>{{ t('history.folders') }}</span></button><button type="button" :aria-label="t('shell.apps')" :title="t('shell.apps')" @click="emit('apps')"><ClientIcon name="apps"/><span>{{ t('shell.apps') }}</span></button></div>
 </aside>
</template>
<script setup>
import {computed,ref} from 'vue';import {ElDropdown,ElDropdownItem,ElDropdownMenu} from 'element-plus';import {t} from '../../i18n/index.js';import {chatText as ct} from '../../i18n/chat.js';import ClientIcon from '../reference/ClientIcon.vue';import BrandLoader from './BrandLoader.vue';import './conversation-shelf.css';
const props=defineProps({open:Boolean,authenticated:Boolean,trash:Boolean,groups:{type:Array,default:()=>[]},folders:{type:Array,default:()=>[]},folderCounts:{type:Object,default:()=>({})},kindCounts:{type:Object,default:()=>({})},folder:{type:String,default:''},query:{type:String,default:''},kind:{type:String,default:'chat'},activeId:String,selected:{type:Array,default:()=>[]},selecting:Boolean,allSelected:Boolean,loading:Boolean,loadingMore:Boolean,busy:Boolean,error:String,total:Number,loaded:{type:Number,default:0},unpinnedTotal:Number,hasMore:Boolean});
const emit=defineEmits(['start','query','kind','folder','folderCommand','trash','refresh','more','choose','command','restore','manage','selectAll','removeSelected','clearUnpinned','addFolder','apps']);const searchOpen=ref(false),activeFolder=computed(()=>props.folders.find(item=>item.id===props.folder));const kinds=[{key:'chat',label:'history.chat'},{key:'app',label:'history.app'},{key:'agent',label:'history.agent'}];
</script>
